/// Stable identifier for one application participating in a Paykit identity.
///
/// App IDs are used for endpoint ownership and private-message attribution.
/// They do not create separate Paykit identities or Encrypted Links.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(try_from = "String", into = "String")]
pub struct PaykitAppId(String);

impl PaykitAppId {
    /// Create a validated Paykit App ID.
    pub fn new(value: impl Into<String>) -> Result<Self> {
        let value = value.into();
        validate_app_id(&value)?;
        Ok(Self(value))
    }

    /// Return the path-safe App ID.
    pub fn as_str(&self) -> &str {
        &self.0
    }

impl PaymentEndpointIdentifier {
    /// Create a new `PaymentEndpointIdentifier` after validating the identifier.
    ///
    /// Returns `Err(PaykitError::Validation)` if the value is empty, too long,
    /// contains forbidden characters, resembles a path-traversal component,
    /// or collides with a reserved identifier.
    pub fn new(id: impl Into<String>) -> Result<Self> {
        let id = id.into();

        if id.is_empty() {
            return Err(PaykitError::Validation(
                "PaymentEndpointIdentifier must not be empty".into(),
            ));
        }

        if id.len() > PAYMENT_ENDPOINT_IDENTIFIER_MAX_LEN {
            return Err(PaykitError::Validation(format!(
                "PaymentEndpointIdentifier must not exceed {PAYMENT_ENDPOINT_IDENTIFIER_MAX_LEN} characters, got {}",
                id.chars().count()
            )));
        }

        if id == PAYMENT_ENDPOINT_IDENTIFIER_RESERVED_PRIVATE {
            return Err(PaykitError::Validation(format!(
                "PaymentEndpointIdentifier '{id}' is reserved for Paykit storage"
            )));
        }

        // Every character must be ASCII alphanumeric, hyphen, underscore, or dot.
        if let Some((pos, ch)) = id
            .char_indices()
            .find(|&(_, ch)| !(ch.is_ascii_alphanumeric() || ch == '-' || ch == '_' || ch == '.'))
        {
            // SECURITY / REDACTION: the identifier can come from decrypted
            // private-message plaintext or remote public data. Report only the
            // code point and byte offset, as `PaymentReference::new` does.
            return Err(PaykitError::Validation(format!(
                "PaymentEndpointIdentifier contains forbidden character U+{:04X} at byte {pos}",
                ch as u32
            )));
        }

        // Reject pure-dot names that are path-traversal components.
        if id.bytes().all(|b| b == b'.') {
            return Err(PaykitError::Validation(format!(
                "PaymentEndpointIdentifier must not be a path-traversal component: \"{id}\""
            )));
        }

        Ok(Self(id))
    }

    /// Access the inner identifier string.
    pub fn as_str(&self) -> &str {
        &self.0
    }

/// Serialized Payment Endpoint Payload served by a Payment Endpoint.
///
/// The payload is UTF-8 text such as JSON, lnurl, or another payment-specific
/// descriptor. If you need to transmit binary payloads, encode them (for
/// example base64) before wrapping in `PaymentEndpointPayload`.
/// Public storage helpers reject payloads larger than
/// [`PAYMENT_ENDPOINT_PAYLOAD_MAX_BYTES`].
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PaymentEndpointPayload(String);

/// Maximum encoded size of one public Payment Endpoint payload.
pub const PAYMENT_ENDPOINT_PAYLOAD_MAX_BYTES: usize = 64 * 1024;
/// Maximum number of public Payment Endpoints fetched for one Paykit App.
pub const PAYMENT_LIST_MAX_ENDPOINTS: usize = 256;

impl PaymentEndpointPayload {
    /// Wrap a UTF-8 string as a Payment Endpoint Payload.
    pub fn new(data: impl Into<String>) -> Self {
        Self(data.into())
    }

    /// Access the inner payload string.
    pub fn as_str(&self) -> &str {
        &self.0
    }

    /// Consume the wrapper and return the inner string.
    pub fn into_inner(self) -> String {
        self.0
    }
}

impl std::fmt::Display for PaymentEndpointPayload {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.0)
    }
}

impl AsRef<str> for PaymentEndpointPayload {
    fn as_ref(&self) -> &str {
        &self.0
    }
}

/// Collection of Payment Endpoints keyed by Payment Endpoint Identifiers.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct PaymentList {
    /// Map of Payment Endpoint Identifier to Payment Endpoint Payload.
    pub payment_endpoints: HashMap<PaymentEndpointIdentifier, PaymentEndpointPayload>,
}

#[instrument(skip(session, payload), fields(identifier = %identifier))]
pub async fn set_payment_endpoint(
    session: &pubky::PubkySession,
    app_id: &PaykitAppId,
    identifier: PaymentEndpointIdentifier,
    payload: PaymentEndpointPayload,
) -> Result<()> {
    debug!("storing payment endpoint");
    pubky_routing::upsert_payment_endpoint(session, app_id, &identifier, &payload)
        .await
        .map_err(|err| map_error("set_payment_endpoint", err))
}

/// Writes or updates a payment endpoint document in the authenticated Pubky session.
#[instrument(skip(session, payload), fields(identifier = %identifier))]
pub async fn upsert_payment_endpoint(
    session: &PubkySession,
    app_id: &PaykitAppId,
    identifier: &PaymentEndpointIdentifier,
    payload: &PaymentEndpointPayload,
) -> Result<()> {
    validate_payment_endpoint_payload(payload)?;
    let path = payment_endpoint_path(app_id, identifier);
    debug!(path = %path, "writing payment endpoint to Pubky storage");
    with_write_lock(session, &path, |lock| async move {
        session
            .storage()
            .put_locked(&lock, payload.as_str().to_string())
            .await
            .map_err(|err| {
                log_payment_endpoint_storage_failure("put", &err);
                PaykitError::Transport {
                    context: "put endpoint".into(),
                    source: err.into(),
                }
            })
            .map(|_| ())
    })
    .await?;
    debug!("payment endpoint stored successfully");
    Ok(())

/// Fetch an app's public Payment Endpoints within caller-supplied aggregate limits.
///
/// The fetch fails if the app publishes more endpoints or total payload bytes
/// than the supplied limits. Per-endpoint protocol limits still apply.
#[instrument(skip(storage))]
pub async fn get_payment_list_with_limits(
    storage: &pubky::PublicStorage,
    payee: &PublicKey,
    app_id: &PaykitAppId,
    max_endpoints: usize,
    max_total_payload_bytes: usize,
) -> Result<PaymentList> {
    let mut remaining_requests = usize::MAX;
    let mut remaining_endpoints = max_endpoints;
    let mut remaining_payload_bytes = max_total_payload_bytes;
    get_payment_list_with_budget(
        storage,
        payee,
        app_id,
        &mut remaining_endpoints,
        &mut remaining_requests,
        &mut remaining_payload_bytes,
    )
    .await
}

/// Fetch an app's public Payment Endpoints using a budget shared across app loads.
///
/// Each directory-page or endpoint request consumes one request before it starts.
/// Each endpoint fetch also consumes one endpoint attempt, regardless of its result.
/// Endpoint body bytes consume the byte budget as they are read, even if the list
/// later fails validation. Missing and empty resources still consume requests.
/// Counters are retained on failure; exhausting the aggregate byte budget saturates
/// that counter at zero. Per-endpoint and per-list protocol limits still apply.
///
/// The caller owns client timeouts, session creation, capability scope, and key
/// rotation. This read only requires public Pubky storage.

/// Conventional prefix for public Paykit data hosted on Pubky storage.
///
pub const PAYKIT_PATH_PREFIX: &str = "/pub/paykit/v0/";

/// Public path for the identity-wide Paykit App Registry.
pub const PAYKIT_APP_REGISTRY_PATH: &str = "/pub/paykit/v0/app-registry.json";

pub(crate) fn payment_endpoint_path_prefix(app_id: &PaykitAppId) -> String {
    format!("{PAYKIT_PATH_PREFIX}apps/{app_id}/endpoints/")
}

pub(crate) fn payment_endpoint_path(
    app_id: &PaykitAppId,
    identifier: &PaymentEndpointIdentifier,
) -> String {
    format!(
        "{}{}",
        payment_endpoint_path_prefix(app_id),
        identifier.as_str()

async fn test_payment_list_fetch_limits_endpoint_count_and_payload_bytes() {
    let setup = TestSetup::new().await;
    for (identifier, payload) in [("endpoint-1", "payload-1"), ("endpoint-2", "payload-2")] {
        set_payment_endpoint(
            &setup.session,
            &app_id(),
            PaymentEndpointIdentifier::new(identifier).unwrap(),
            PaymentEndpointPayload::new(payload),
        )
        .await
        .unwrap();
    }

    let list =
        get_payment_list_with_limits(&setup.public_storage, &setup.public_key, &app_id(), 2, 18)
            .await
            .unwrap();
    assert_eq!(list.payment_endpoints.len(), 2);

    let endpoint_limit =
        get_payment_list_with_limits(&setup.public_storage, &setup.public_key, &app_id(), 1, 18)
            .await;
    let endpoint_limit = endpoint_limit.unwrap_err();
    assert!(matches!(endpoint_limit, PaykitError::InvalidData { .. }));
    assert!(is_payment_list_limit_exceeded(&endpoint_limit));

    let payload_limit =
        get_payment_list_with_limits(&setup.public_storage, &setup.public_key, &app_id(), 2, 8)
            .await;
    let payload_limit = payload_limit.unwrap_err();
    assert!(matches!(payload_limit, PaykitError::InvalidData { .. }));
    assert!(is_payment_list_limit_exceeded(&payload_limit));

/// Amount of value in a payment flow, expressed as decimal text plus asset.
///
/// # Validation
///
/// [`PaymentAmount::new`] accepts a `value` consisting only of ASCII digits and
/// at most one decimal point, with at least one digit. Leading `+` and `-` signs
/// are rejected. Values such as `.5` and `10.` are accepted. The `asset` must be
/// non-empty and contain no control characters. Beyond these checks, Paykit
/// defines no range, precision, scale, normalization, or asset-registry policy.

impl PaymentAmount {
    /// Access the preserved decimal spelling.
    pub fn value(&self) -> &str {
        &self.value
    }
    /// Access the exact asset text.
    pub fn asset(&self) -> &str {
        &self.asset
    }

    /// Create a Payment Amount after validating its value and asset fields.
    pub fn new(value: impl Into<String>, asset: impl Into<String>) -> Result<Self> {
        Self::new_with_label(value.into(), asset.into(), "Payment Amount")
    }

    pub(crate) fn new_with_label(
        value: String,
        asset: String,
        label: &'static str,
    ) -> Result<Self> {
        let amount = Self { value, asset };
        amount.validate_with_label(label)?;
        Ok(amount)
    }

    pub(crate) fn validate_with_label(&self, label: &'static str) -> Result<()> {
        validate_decimal_text(&self.value, format_args!("{label}.value"))?;
        validate_asset_text(&self.asset, "Payment Amount asset")
    }

#[test]
fn payment_amount_accepts_decimal_value_and_asset() {
    let amount = PaymentAmount::new("10.00", "usd").unwrap();
    assert_eq!(amount.value, "10.00");
    assert_eq!(amount.asset, "usd");
}

#[test]
fn payment_amount_rejects_invalid_value() {
    let err = PaymentAmount::new("ten", "usd").unwrap_err();
    assert!(matches!(err, PaykitError::Validation(msg) if msg.contains("decimal string")));
}

impl PaymentReference {
    /// Create a Payment Reference after validating that the input is non-empty,
    /// bounded, and free of control characters.
    pub fn new(reference: impl Into<String>) -> Result<Self> {
        let reference = reference.into();
        if reference.is_empty() {
            return Err(PaykitError::Validation(
                "Payment Reference must not be empty".into(),
            ));
        }
        let char_count = reference.chars().count();
        if char_count > PAYMENT_REFERENCE_MAX_LEN {
            return Err(PaykitError::Validation(format!(
                "Payment Reference must not exceed {PAYMENT_REFERENCE_MAX_LEN} characters, got {char_count}"
            )));
        }
        if let Some((pos, ch)) = reference.char_indices().find(|&(_, ch)| ch.is_control()) {
            return Err(PaykitError::Validation(format!(
                "Payment Reference must not contain control character U+{:04X} at byte {pos}",
                ch as u32
            )));
        }
        Ok(Self(reference))
    }

/// UUID-v4 identifier for one Event Message.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct EventId(String);

impl EventId {
    /// Create an Event ID from a UUID-v4 string.
    pub fn new(id: impl Into<String>) -> Result<Self> {
        validate_uuid_v4(id.into(), "Event ID").map(Self)
    }

    /// Generate a fresh Event ID.
    pub fn new_v4() -> Self {
        Self(uuid::Uuid::new_v4().to_string())
    }

    /// Access the canonical UUID string.
    pub fn as_str(&self) -> &str {
        &self.0
    }

/// UUID-v4 identifier for one Payment Request.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct PaymentRequestId(String);

impl PaymentRequestId {
    /// Create a Payment Request ID from a UUID-v4 string.
    pub fn new(id: impl Into<String>) -> Result<Self> {
        validate_uuid_v4(id.into(), "Payment Request ID").map(Self)
    }

    /// Generate a fresh Payment Request ID.
    pub fn new_v4() -> Self {
        Self(uuid::Uuid::new_v4().to_string())
    }

    /// Access the canonical UUID string.
    pub fn as_str(&self) -> &str {
        &self.0
    }

impl PaymentRequestTerms {
    /// Start constructing terms with their required amount, reference, and endpoints.
    ///
    /// Call [`PaymentRequestTermsBuilder::build`] to validate the complete terms.
    pub fn builder(
        amount: PaymentAmount,
        payment_reference: PaymentReference,
        accepted_payment_endpoint_identifiers: Vec<PaymentEndpointIdentifier>,
    ) -> PaymentRequestTermsBuilder {
        PaymentRequestTermsBuilder(Self {
            amount,
            payment_reference,
            accepted_payment_endpoint_identifiers,
            payment_endpoints: None,
            required_app_id: None,
            proposal_expires_at: None,
            recurrence: None,
            conversion: None,
            payment_deadline: None,
            metadata: JsonMap::new(),
        })
    }
}

impl PaymentRequestTermsBuilder {
    /// Bind payment to immutable Payment Endpoints owned by `required_app_id`.
    ///
    /// A supplied map must be nonempty, contain nonempty payloads, and use only
    /// accepted Payment Endpoint Identifiers. `required_app_id` must be set.
    /// `None` preserves endpoint discovery; `Some` forbids fallback outside the map.
    pub fn payment_endpoints(
        mut self,
        value: Option<HashMap<PaymentEndpointIdentifier, PaymentEndpointPayload>>,
    ) -> Self {
        self.0.payment_endpoints = value;
        self
    }
    /// Constrain payment to an endpoint owned by the specified payee App.
    pub fn required_app_id(mut self, value: Option<crate::PaykitAppId>) -> Self {
        self.0.required_app_id = value;
        self
    }

/// Validate the complete terms, including the non-empty endpoint list.
pub fn build(self) -> Result<PaymentRequestTerms> {
    self.0.validate()?;
    Ok(self.0)
}

impl PaymentRequest {
    pub(super) fn validate(&self) -> Result<()> {
        crate::validation::validate_outgoing_version_kind(
            self.version,
            self.kind,
            PrivateMessageKind::PaymentRequest,
            "Payment Request",
        )?;
        self.request.validate()
    }

    /// Construct a Payment Request proposal using protocol version 1.
    pub fn new(
        event_id: EventId,
        payment_request_id: PaymentRequestId,
        request: PaymentRequestTerms,
    ) -> Self {
        Self {
            version: 1,
            kind: PrivateMessageKind::PaymentRequest,
            event_id,
            payment_request_id,
            request,
        }
    }

/// Serialize a Payment Request protocol Event Message to canonical JSON.
pub fn serialize_payment_request_event(
    app_id: &PaykitAppId,
    event: &PaymentRequestEvent,
) -> Result<String> {
    match event {
        PaymentRequestEvent::Request(event) => serialize_payment_request_json(app_id, event),
        PaymentRequestEvent::Acceptance(event) => serialize_acceptance_json(app_id, event),
        PaymentRequestEvent::Rejection(event) => serialize_rejection_json(app_id, event),
        PaymentRequestEvent::Cancellation(event) => serialize_cancellation_json(app_id, event),
        PaymentRequestEvent::Proof(event) => serialize_payment_proof_json(app_id, event),
        PaymentRequestEvent::ConversionQuote(event) => {
            serialize_conversion_quote_json(app_id, event)
        }
    }
}

/// Parse a raw Private Application Message as a Payment Request protocol event.
///
/// Returns `None` when the message kind is not one of the Payment Request
/// protocol event kinds. Recognized but malformed Payment Request events return
/// `Some` with [`PaymentRequestEventMessage::is_valid`] set to `false`.
pub fn parse_payment_request_event_message(
    message: &PrivateApplicationMessage,
) -> Option<PaymentRequestEventMessage> {
    let kind = message.known_kind()?;
    let event = parse_event(kind, &message.raw_json)?.map_err(|err| err.to_string());
    let (app_id, event_id, payment_request_id) = parse_event_header(&message.raw_json);
    Some(PaymentRequestEventMessage {
        kind,
        app_id,
        event_id,
        payment_request_id,
        raw_json: message.raw_json.clone(),
        event,
    })
}

        self.app_id.as_ref()
    }

    /// Whether the recognized event message parsed successfully.
    pub fn is_valid(&self) -> bool {
        self.event.is_ok()
    }

    /// Access the parsed event when structural validation succeeded.
    pub fn parsed_event(&self) -> Option<&PaymentRequestEvent> {
        self.event.as_ref().ok()
    }

    /// Access the validation error when structural validation failed.
    pub fn validation_error(&self) -> Option<&str> {
        self.event.as_ref().err().map(String::as_str)
    }

    /// Access the Event ID.
    ///
    /// Returns `None` when the recognized message is malformed and the Event ID
    /// could not be parsed as a valid Event ID.
    pub fn event_id(&self) -> Option<&EventId> {
        self.event_id.as_ref()
    }

    /// Access the Payment Request ID shared by this lifecycle event.
    ///
    /// Returns `None` when the recognized message is malformed and the Payment
    /// Request ID could not be parsed as a valid Payment Request ID.
    pub fn payment_request_id(&self) -> Option<&PaymentRequestId> {
        self.payment_request_id.as_ref()
    }
}

/// Send a `paykit.payment_request` Event Message.
///
/// Payment Requests are payee-initiated; caller code must enforce the sender
/// role.
#[instrument(skip(link, event))]
pub async fn send_payment_request(
    link: &mut EncryptedLink,
    app_id: &PaykitAppId,
    event: &PaymentRequest,
) -> Result<()> {
    let json = serialize_payment_request_json(app_id, event)
        .map_err(|err| map_error("send_payment_request", err))?;
    link.send_payment_request_message(json.as_bytes())
        .await
        .map_err(|err| map_error("send_payment_request", err))
}

/// Send a `paykit.payment_request_acceptance` Event Message.
///
/// Acceptances are payer-initiated; caller code must enforce the sender role.
#[instrument(skip(link, event))]
pub async fn send_payment_request_acceptance(
    link: &mut EncryptedLink,
    app_id: &PaykitAppId,
    event: &PaymentRequestAcceptance,
) -> Result<()> {
    let json = serialize_acceptance_json(app_id, event)
        .map_err(|err| map_error("send_payment_request_acceptance", err))?;
    link.send_payment_request_acceptance_message(json.as_bytes())
        .await
        .map_err(|err| map_error("send_payment_request_acceptance", err))
}

/// One Private Application Message received from an Encrypted Link.
///
/// This is the low-level receive item for the Private Application Message stream.
/// It keeps the raw plaintext payload so callers can route and persist messages
/// themselves. If decrypted bytes are not UTF-8, `raw_json` contains a local
/// invalid-JSON marker with the bytes encoded as base64url. Higher layers should
/// treat that marker as malformed input, not as a Private Application Message.
#[derive(Clone, PartialEq, Eq)]
pub struct PrivateApplicationMessage {
    /// Private Application Message version from the JSON `version` field, when
    /// the field is present and can be represented as a `u8`.
    pub version: Option<u8>,
    /// Message kind string from the JSON `kind` field, when the field is a
    /// string.
    pub kind: Option<String>,
    /// App ID string from the JSON `app_id` field, when the field is a string.
    pub app_id: Option<String>,
    /// Raw plaintext received over the Encrypted Link.
    pub raw_json: String,
}

impl std::fmt::Debug for PrivateApplicationMessage {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PrivateApplicationMessage")
            .field("version", &self.version)
            .field("kind", &self.kind)
            .field("app_id", &self.app_id)
            .field(
                "raw_json",
                &format_args!("<redacted:{} bytes>", self.raw_json.len()),
            )
            .finish()

#[test]
fn payment_request_event_serialization_supports_outbound_idempotency() {
    let request = payment_request();
    let event = PaymentRequestEvent::Request(request.clone());

    let serialized = serialize_payment_request_event(&test_app_id(), &event).unwrap();
    let parsed = parse_payment_request_raw(PrivateMessageKind::PaymentRequest, &serialized);

    assert_eq!(parsed.parsed_event(), Some(&event));
    assert_eq!(parsed.event_id(), Some(request.event_id()));
    assert!(serialized.contains("\"proposal_expires_at\""));

#[test]
fn payment_request_events_return_malformed_recognized_events_for_persistence() {
    let malformed = r#"{"version":1,"kind":"paykit.payment_request","app_id":"test-app","event_id":"not-a-uuid","payment_request_id":"b7f9c2a1-6d43-4b0e-a8d4-0fe2c712ab33","request":{"amount":{"value":"0.001","asset":"btc"},"payment_reference":"invoice-2026-0001","proposal_expires_at":null,"recurrence":null,"accepted_payment_endpoint_identifiers":["btc-lightning-bolt11"],"required_app_id":null,"metadata":{}}}"#;
    let acceptance = PaymentRequestAcceptance::new(
        EventId::new("8a0d8b4c-913f-4e31-9f2c-2a6f5bb4d102").unwrap(),
        request_id(),
    );

    let malformed_event = parse_payment_request_raw(PrivateMessageKind::PaymentRequest, malformed);
    let acceptance_raw = json!({
        "version": 1,
        "kind": "paykit.payment_request_acceptance",
        "app_id": test_app_id().as_str(),
        "event_id": acceptance.event_id().as_str(),
        "payment_request_id": acceptance.payment_request_id().as_str(),
    })
    .to_string();
    let acceptance_event = parse_payment_request_raw(
        PrivateMessageKind::PaymentRequestAcceptance,
        &acceptance_raw,
    );

    assert_eq!(malformed_event.kind(), PrivateMessageKind::PaymentRequest);
    assert_eq!(malformed_event.raw_json, malformed);
    assert!(!malformed_event.is_valid());
    assert!(malformed_event.parsed_event().is_none());
    assert!(malformed_event
        .validation_error()
        .is_some_and(|err| err.contains("Event ID")));
    assert_eq!(malformed_event.event_id(), None);
    assert_eq!(malformed_event.payment_request_id(), Some(&request_id()));
    assert_eq!(
        acceptance_event.parsed_event(),
        Some(&PaymentRequestEvent::Acceptance(acceptance))
    );

