/// Local receipt issuance state.
#[derive(uniffi::Enum, Clone, Copy, Debug, PartialEq, Eq)]
pub enum FfiReceiptIssuanceStatus {
    /// Encrypted Receipt has not been stored yet.
    PendingStorage,
    /// Encrypted Receipt was stored, but Receipt Access has not been queued yet.
    Stored,
    /// Receipt Access was queued for private delivery.
    AccessQueued,
    /// Last storage or queueing attempt failed.
    Failed,
    /// Receipt Access was published to the counterparty.
    AccessSent,
    /// Receipt Access delivery stopped without automatic retry; `last_error`
    /// carries the failure. Recovering the Encrypted Link queues it again.
    AccessFailed,
    /// SDK returned a value this binding version does not understand.
    Unknown,
}

/// App-facing view of local receipt issuance progress.
#[derive(uniffi::Record, Clone)]
pub struct FfiReceiptIssuanceView {
    /// Counterparty that should receive Receipt Access.
    pub counterparty: String,
    /// Application issuing the Receipt.
    pub app_id: String,
    /// Receipt ID.
    pub receipt_id: String,
    /// Receipt Access Event ID.
    pub receipt_access_event_id: String,
    /// Payment Reference copied from the Receipt.
    pub payment_reference: Arc<FfiPaymentReference>,
    /// Optional Payment Request ID copied from the Receipt.
    pub payment_request_id: Option<String>,
    /// Optional Billing Period copied from the Receipt.
    pub billing_period: Option<FfiBillingPeriod>,
    /// Optional Payment Endpoint Identifier copied from the Receipt.
    pub payment_endpoint_identifier: Option<String>,
    /// Optional Payment Amount copied from the Receipt.
    pub amount: Option<FfiReceiptAmount>,
    /// Current issuance status.
    pub status: FfiReceiptIssuanceStatus,
    /// Outbound private message id that carries Receipt Access, once queued.
    pub outbound_message_id: Option<u64>,
    /// Creation time as RFC3339 text.
    pub created_at: String,
    /// Last change to the issuance or its Receipt Access delivery as RFC3339
    /// text: each delivery attempt, failure, recovery requeue, publication or
    /// Delivery Confirmation moves it, and it never moves backwards.
    pub updated_at: String,
    /// Time the Encrypted Receipt was stored as RFC3339 text.
    pub stored_at: Option<String>,
    /// Time Receipt Access was queued for private delivery as RFC3339 text.
    pub access_queued_at: Option<String>,
    /// Last storage, queueing or Receipt Access delivery error. While the
    /// status stays `AccessQueued`, the outbound queue retries delivery.
    pub last_error: Option<String>,

/// List issued receipts across non-blocked counterparties, newest first.
///
/// Each status includes Receipt Access delivery (`AccessSent` or
/// `AccessFailed`) from whichever call drained the outbound queue, so a
/// wallet needs no bookkeeping of its own around those calls.
pub async fn issued_receipts(&self) -> Result<Vec<ReceiptIssuanceView>> {
    let (_, identity) = self.load_session_access_and_refresh_identity().await?;
    if identity.public_key.is_none() {
        return Ok(Vec::new());
    }
    self.storage
        .transaction(|tx| {
            let snapshot = tx.export_storage_state();
            let outbound = snapshot
                .outbound_private_messages
                .iter()
                .map(|message| (message.outbound_message_id, message))
                .collect::<HashMap<_, _>>();
            let mut records = snapshot
                .receipt_issuance_records
                .values()
                .filter(|record| {
                    !snapshot
                        .linked_peers
                        .get(&record.counterparty)
                        .is_some_and(|peer| peer.state == LinkedPeerState::Blocked)
                })
                .map(|record| {
                    let access = record
                        .outbound_message_id
                        .and_then(|id| outbound.get(&id).copied());
                    ReceiptIssuanceView::with_access_delivery(record, access)
                })
                .collect::<Vec<_>>();
            records.sort_by_key(|record| Reverse(record.created_at));
            Ok(records)
        })
        .await
}

let view = views().await;
assert_eq!(view.status, ReceiptIssuanceStatus::AccessQueued);
assert_eq!(view.outbound_message_id, Some(outbound_message_id));
assert_eq!(view.updated_at, queued_at);
assert!(view.last_error.is_none());

// A failed attempt is retried, so the receipt stays queued with the error.
set_outbound(attempt_failed(at(10))).await;
let view = views().await;
assert_eq!(view.status, ReceiptIssuanceStatus::AccessQueued);
assert_eq!(view.last_error.as_deref(), Some("timeout"));
assert_eq!(view.updated_at, at(10));

set_outbound(Box::new(move |message| {
    mark_outbound_invalid(message, "bad payload".into(), at(5))
}))
.await;
let view = views().await;
assert_eq!(view.status, ReceiptIssuanceStatus::AccessFailed);
assert_eq!(view.last_error.as_deref(), Some("bad payload"));
assert_eq!(view.updated_at, at(10));

set_outbound(Box::new(move |message| {
    mark_outbound_recovery_required(message, "link lost".into(), at(11))
}))
.await;
let view = views().await;
assert_eq!(view.status, ReceiptIssuanceStatus::AccessFailed);
assert_eq!(view.last_error.as_deref(), Some("link lost"));
assert_eq!(view.updated_at, at(11));

// Encrypted Link recovery queues the access again under a rolled-back clock.
recover(at(6)).await;
let view = views().await;
assert_eq!(view.status, ReceiptIssuanceStatus::AccessQueued);
assert!(view.last_error.is_none());
assert_eq!(view.updated_at, at(11));

// An ambiguous failed publication leaves `sent_at` empty; the peer's
// confirmation, read under a rolled-back clock, still proves delivery.
set_outbound(attempt_failed(at(12))).await;
confirm(at(7)).await;
let view = views().await;
assert_eq!(view.status, ReceiptIssuanceStatus::AccessSent);
assert_eq!(view.updated_at, at(12));

// Recovery completes the confirmed message under a rolled-back clock.
set_outbound(Box::new(move |message| {
    mark_outbound_recovery_required(message, "rotated".into(), at(13))
}))
.await;
recover(at(8)).await;
let view = views().await;
assert_eq!(view.status, ReceiptIssuanceStatus::AccessSent);
assert_eq!(view.updated_at, at(13));

async fn resolve_public_contact_payment_with_terms(
    &self,
    counterparty: PubkyPublicKey,
    amount: Option<PaymentAmountContext>,
    payment_request_terms: Option<PaymentRequestTermsRecord>,
) -> Result<PublicContactPaymentResolution> {
    if payment_request_terms
        .as_ref()
        .is_some_and(|terms| terms.payment_endpoints.is_some())
    {
        return Ok(unresolved_public_resolution(false, Vec::new(), 0));
    }
    let required_app_id = payment_request_terms
        .as_ref()
        .and_then(|terms| terms.required_app_id.as_ref());
    // Only a received Payment Request refuses a blocked counterparty;
    // plain contact resolution ignores Linked Peer state.
    let refuse_blocked_counterparty = payment_request_terms.is_some();
    let loaded = self
        .public_payment_candidates(&counterparty, required_app_id, refuse_blocked_counterparty)
        .await;
    // A block can land while the Payment Endpoint reads are in flight.
    // Those reads cannot be recalled without serializing against
    // `block_peer`, so the guarantee is that no candidate reaches the
    // payment adapter once a block is observed, and the call returns
    // `Policy`, outranking a loading error or a `NoEndpoint` result.
    self.ensure_peer_not_blocked_if(refuse_blocked_counterparty, &counterparty)
        .await?;
    let mut batch = loaded?;
    filter_public_candidates_for_request(&mut batch.candidates, payment_request_terms.as_ref());
    if batch.candidates.is_empty() {
        return Ok(unresolved_public_resolution(
            false,
            batch.failures,
            batch.loaded_app_count,
        ));
    }

    self.resolve_public_candidate_batch_with_failures(
        counterparty,
        amount,
        batch.candidates,
        batch.failures,
        batch.loaded_app_count,
        refuse_blocked_counterparty,
    )
    .await

/// Pubky client configuration owned by the binding layer.
///
/// Identity records use HTTP PKARR relays, including on local testnets. Clients do
/// not connect directly to the DHT; successful publication still awaits the relay.
#[derive(uniffi::Record, Clone, Debug, PartialEq, Eq)]
pub struct FfiPubkyClientConfig {
    /// Request timeout for Pubky HTTP operations in seconds.
    pub request_timeout_secs: u64,
    /// Host running local testnet services, or `None` to use the public Pubky network.
    ///
    /// Unless an explicit grant-auth relay overrides it, grant auth uses the
    /// standard local testnet relay at `http://<host>:15412/inbox/`.
    pub local_testnet_host: Option<String>,
    /// Explicit grant-auth relay inbox URL, or `None` to use Pubky's default.
    pub auth_relay_url: Option<String>,
}

pub(crate) fn pubky_from_config(config: &FfiPubkyClientConfig) -> Result<Pubky, PaykitFfiError> {
    pubky_client_builder(config)?
        .build()
        .map(Pubky::with_client)
        .map_err(|err| identity_error("pubky_client", format!("create Pubky client failed: {err}")))
}

pub(crate) fn pubky_client_builder(
    config: &FfiPubkyClientConfig,
) -> Result<pubky::PubkyHttpClientBuilder, PaykitFfiError> {
    if config.request_timeout_secs == 0 {
        return Err(validation_error(
            "pubky request timeout must be greater than zero",
        ));
    }

    let mut builder = PubkyHttpClient::builder();
    if let Some(host) = config.local_testnet_host.as_deref() {
        validate_local_testnet_host(host)?;
        builder.testnet_with_host(host);
    }
    // Mobile networks may block UDP. Relays perform DHT access; waiting for a second,
    // direct DHT operation would delay signup even after the relay succeeds.
    builder.pkarr(|pkarr| pkarr.no_dht());
    builder.request_timeout(Duration::from_secs(config.request_timeout_secs));
    Ok(builder)
}

/// Pubky app profile path, read by profile fallback and written by the Pubky app profile APIs.
pub const PUBKY_PROFILE_PATH: &str = "/pub/pubky.app/profile.json";
/// Pubky app follows path used by read-only helper APIs.
pub const PUBKY_FOLLOWS_PATH_PREFIX: &str = "/pub/pubky.app/follows/";
/// Pubky social v1 profile path, which replaces [`PUBKY_PROFILE_PATH`] once pubky.app migrated the identity.
pub const SOCIAL_V1_PROFILE_PATH: &str = "/pub/social/v1/profile.json";
/// Pubky social v1 follows path, which replaces [`PUBKY_FOLLOWS_PATH_PREFIX`] once pubky.app migrated the
/// identity. Each follow is `<followed key>.json`.
pub const SOCIAL_V1_FOLLOWS_PATH_PREFIX: &str = "/pub/social/v1/follows/";

/// Fetch a public Pubky app profile, from Pubky social v1 when it has one
/// there, else from pubky.app (v0).
pub async fn fetch_pubky_profile(
    &self,
    public_key: PubkyPublicKey,
) -> Result<Option<PubkyProfileRecord>> {
    let public_storage =
        self.pubky
            .load_public_storage()
            .await?
            .ok_or_else(|| PaykitSdkError::Identity {
                context: "no Pubky public storage available for Pubky profile lookup".into(),
                source: None,
            })?;
    for path in [SOCIAL_V1_PROFILE_PATH, PUBKY_PROFILE_PATH] {
        if let Some(raw_json) = fetch_public_text(
            &public_storage,
            &public_key,
            path,
            "fetch Pubky profile",
            MAX_PUBLIC_PROFILE_BYTES,
        )
        .await?
        {
            return Ok(Some(PubkyProfileRecord {
                public_key,
                profile: parse_pubky_profile_json(&raw_json)?,
                path: path.into(),
                fetched_at: self.clock.now(),
            }));
        }
    }
    Ok(None)
}

/// Apply `update` to this identity's Pubky app profile.
///
/// Only the fields `update` names change; every other stored key is kept.
/// Pass `None` to create the first profile, or the revision from
/// [`Self::fetch_pubky_profile_with_revision`]. The write runs under a
/// homeserver lock and returns [`PaykitSdkError::ConcurrentUpdate`] when
/// the stored profile no longer matches `expected_revision`. It goes to the
/// layout pubky.app's migration flag names: Pubky social v1 once pubky.app
/// migrated the identity, else pubky.app (v0). The session must hold
/// [`PUBKY_APP_PROFILE_SESSION_CAPABILITIES`], else this returns
/// [`PaykitSdkError::Identity`]; session capabilities remain the caller's
/// responsibility.
pub async fn publish_pubky_profile(
    &self,
    update: PubkyProfileUpdate,
    expected_revision: Option<String>,
) -> Result<PubkyProfileSnapshot> {
    let (session_access, _) = self.load_session_access_and_refresh_identity().await?;
    let session_access = session_access.ok_or_else(|| PaykitSdkError::Identity {
        context: "no Pubky session available for Pubky profile publication".into(),
        source: None,
    })?;
    let public_key = session_access.public_key()?;
    let version = own_social_version(&session_access).await?;
    let path = version.profile_path();
    let current = match self.fetch_pubky_profile_raw(&public_key, path).await? {
        Some((raw, revision)) if Some(&revision) == expected_revision.as_ref() => Some(raw),
        None if expected_revision.is_none() => None,
        _ => return Err(pubky_profile_changed()),
    };
    let bytes = merge_pubky_profile_json(current.as_deref(), &update, version)?;
    let revision = paykit_lib::content_revision(&bytes);
    let profile = parse_pubky_profile_json(std::str::from_utf8(&bytes).map_err(|_| {
        PaykitSdkError::Protocol {
            context: "encoded Pubky profile is not UTF-8".into(),
            source: None,
        }
    })?)?;
    // The lock re-checks the revision, so the merge above used exactly the stored bytes.
    paykit_lib::put_resource_if_revision(
        &session_access.session,
        path,
        bytes,
        expected_revision.as_deref(),
        MAX_PUBKY_PROFILE_BYTES,
    )
    .await
    .map_err(scope_error)?;
    Ok(PubkyProfileSnapshot {
        public_key,
        profile,
        revision,
        fetched_at: self.clock.now(),
    })
}

/// Pubky app blob path prefix. Blob ids are content hashes.
pub const PUBKY_APP_BLOB_PATH_PREFIX: &str = "/pub/pubky.app/blobs/";
/// Pubky app file path prefix. File ids are timestamps.
pub const PUBKY_APP_FILE_PATH_PREFIX: &str = "/pub/pubky.app/files/";
/// Pubky social v1 file path prefix. A file is the raw bytes at `<content hash>.<extension>`.
pub const SOCIAL_V1_FILE_PATH_PREFIX: &str = "/pub/social/v1/files/";
/// The private flag pubky.app writes once it migrated an identity to Pubky social v1.
pub const SOCIAL_V1_MIGRATION_FLAG_PATH: &str = "/priv/social/v1/_migrated.json";
/// The lowest migration flag `transform_rev` pubky.app counts as migrated.
const SOCIAL_V1_MIN_TRANSFORM_REV: u64 = 3;
/// Session capabilities needed to write the Pubky app profile and its avatar.
///
/// They cover both the pubky.app (v0) and the Pubky social v1 layouts, and
/// reading pubky.app's migration flag, which picks between them. Apps that
/// edit the shared Pubky app profile add these to their own session scope.
/// They are not part of the Paykit session scopes.
pub const PUBKY_APP_PROFILE_SESSION_CAPABILITIES: &str = "/pub/pubky.app/profile.json:rw,\
/pub/pubky.app/blobs/:rw,/pub/pubky.app/files/:rw,/pub/social/v1/profile.json:rw,\
/pub/social/v1/files/:rw,/priv/social/v1/_migrated.json:r";
/// The capability to read pubky.app's migration flag.
pub(crate) const SOCIAL_V1_MIGRATION_FLAG_CAPABILITY: &str = "/priv/social/v1/_migrated.json:r";

/// The layout an identity's Pubky app profile, follows and avatar use.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum SocialVersion {
    /// `/pub/pubky.app/`, until pubky.app migrates the identity.
    V0,
    /// `/pub/social/v1/`, once pubky.app migrated the identity.
    V1,
}

impl SocialVersion {
    /// The version pubky.app's migration flag records, as pubky.app reads it:
    /// a missing or unreadable flag, or one below the current transform, is v0.
    pub(crate) fn from_migration_flag(flag: Option<&[u8]>) -> Self {
        let transform_rev = flag
            .and_then(|bytes| serde_json::from_slice::<JsonValue>(bytes).ok())
            .and_then(|flag| flag.get("transform_rev").and_then(JsonValue::as_u64));
        if transform_rev.is_some_and(|rev| rev >= SOCIAL_V1_MIN_TRANSFORM_REV) {
            Self::V1
        } else {
            Self::V0
        }
    }

    pub(crate) fn profile_path(self) -> &'static str {
        match self {
            Self::V0 => PUBKY_PROFILE_PATH,
            Self::V1 => SOCIAL_V1_PROFILE_PATH,
        }
    }

    pub(crate) fn follows_path_prefix(self) -> &'static str {
        match self {
            Self::V0 => PUBKY_FOLLOWS_PATH_PREFIX,
            Self::V1 => SOCIAL_V1_FOLLOWS_PATH_PREFIX,
        }
    }
}

/// Queue reservation-backed Private Payment Lists and process their queues.
///
/// Each update is the complete Private Payment List for one counterparty.
/// An update with no reservations queues an empty Private Payment List for
/// that counterparty. When `clear_unlisted_linked_peers` is true, linked
/// peers that are not included in `updates` also receive empty lists.
/// Counterparties with an in-progress Encrypted Link can still have their
/// lists queued; they remain eligible for a later outbound worker run after
/// the link reaches `Linked`.
/// Unchanged lists with the same reservations reuse their existing outbound
/// record, including lists already sent on the current Encrypted Link.
/// Outbound retries and reservation cleanup still run for reused records.
/// After a restart, a sent list is reused only when the stored link state
/// still matches the peer record and the list was sent more than five
/// minutes after the peer's last link change or private receive; otherwise
/// it is republished once.
pub async fn sync_private_payment_lists_with_reservations_and_process_outbound(
    &self,
    updates: Vec<PrivatePaymentListReservationUpdate>,
    clear_unlisted_linked_peers: bool,
) -> Result<PrivatePaymentListDeliveryReport> {
    // Bound the composed future's stack size and type depth for FFI callers.
    self.sync_private_payment_lists_with_reservations(
        updates,
        clear_unlisted_linked_peers,
        true,
    )
    .boxed()
    .await
}

/// Return the sent Private Payment List an unchanged sync may reuse.
///
/// Without a runtime witness, for example after a restart, this falls back
/// to durable timestamps so unchanged lists are not republished on every
/// launch. The fallback is not delivery evidence, so acknowledgements use
/// `published_private_payment_list_id` instead.
fn reusable_private_payment_list_id(
    &self,
    tx: &dyn StorageTransaction,
    counterparty: &PubkyPublicKey,
) -> Option<u64> {
    self.published_private_payment_list_id(tx, counterparty)
        .or_else(|| {
            // Reusing a sent row queues nothing, so the outbound restore that
            // rejects a stale or misassociated link never runs. Apply its
            // stored-state checks here; a mismatch republishes the list and
            // leaves recovery to the outbound worker.
            let (_, snapshot, _) = associated_link_snapshot(tx, counterparty)?;
            snapshot.link_id()?;
            private_payment_list_sent_after_last_link_change(
                tx,
                counterparty,
                &self.config.app_id,
            )
        })
}

/// Clock difference tolerated between Paykit Apps that share one identity's
/// state. Their clocks stamp `sent_at` and `last_sync_at` independently.
const PRIVATE_PAYMENT_LIST_REUSE_CLOCK_MARGIN: ChronoDuration = ChronoDuration::minutes(5);

fn latest_private_payment_list(
    tx: &dyn StorageTransaction,
    counterparty: &PubkyPublicKey,
    app_id: &PaykitAppId,
) -> Option<OutboundPrivateMessageRecord> {
    tx.outbound_private_messages(counterparty)
        .into_iter()
        .filter(|message| {
            message.app_id == *app_id
                && message.kind == PrivateMessageKind::PrivatePaymentList.as_str()
        })
        .max_by_key(|message| message.outbound_message_id)
}

/// Return the latest sent Private Payment List from `app_id` when durable state
/// shows it was published after the last Encrypted Link change.
///
/// This lets a restarted runtime reuse an unchanged list without a stored
/// delivery witness. `last_sync_at` advances whenever the peer's link state
/// changes (establishment, recovery, block, unblock) and on private receives,
/// so a list sent later than that, by more than the clock margin, went out on
/// the current Encrypted Link. Receives make the check conservative: a list
/// sent before one is republished once instead of reused. The caller must
/// confirm that the current link snapshot still matches the stored peer
/// record, because reuse skips the outbound restore that would check it.
pub(crate) fn private_payment_list_sent_after_last_link_change(
    tx: &dyn StorageTransaction,
    counterparty: &PubkyPublicKey,
    app_id: &PaykitAppId,
) -> Option<u64> {
    let peer = tx.linked_peer(counterparty)?;
    if peer.state != LinkedPeerState::Linked {
        return None;
    }
    let last_link_change = peer.last_sync_at?;
    let latest = latest_private_payment_list(tx, counterparty, app_id)?;
    if latest.status != OutboundPrivateMessageStatus::Sent {
        return None;
    }
    // Recovery requeues clear `sent_at`, so it always names a publication made
    // after the message last returned to the retry path.
    let sent_at = latest.sent_at?;
    (sent_at > last_link_change + PRIVATE_PAYMENT_LIST_REUSE_CLOCK_MARGIN)
        .then_some(latest.outbound_message_id)
}

if let PrivatePaymentListQueuePolicy::Sync { sent_message_id } = policy {
    // Pending, sending, and failed messages remain on the retry path, so
    // they can be reused. A sent message is reusable only when the caller
    // showed it was delivered on the current Encrypted Link.
    if let Some(message) = latest_private_payment_list(tx, &counterparty, &message_app_id) {
        let reusable = match message.status {
            OutboundPrivateMessageStatus::Pending
            | OutboundPrivateMessageStatus::Sending
            | OutboundPrivateMessageStatus::Failed => true,
            OutboundPrivateMessageStatus::Sent => {
                sent_message_id == Some(message.outbound_message_id)
            }
            _ => false,
        };
        let same_reservations = checked_drafts.iter().all(|(_, existing)| {
            existing.as_ref().is_some_and(|record| {
                record.outbound_message_id == message.outbound_message_id
                    && record.expires_at.is_none_or(|expiry| expiry > now)
            })
        }) && tx
            .payment_endpoint_reservations(&counterparty)
            .iter()
            .filter(|record| record.outbound_message_id == message.outbound_message_id)
            .count()
            == checked_drafts.len();
        if reusable
            && same_reservations
            && parse_private_payment_list_json(&message.raw_json)
                .is_ok_and(|stored| stored == list)
        {
            return Ok(message);
        }

let (handshake_pending, statuses, acknowledged) = self
    .storage
    .transaction(|tx| {
        let readiness = Self::private_queue_readiness_in_transaction(tx, counterparty);
        let handshake_pending =
            matches!(readiness, Ok(PrivateQueueReadiness::PendingHandshake));
        let messages = tx.outbound_private_messages(counterparty);
        let latest_list_id = messages
            .iter()
            .filter(|message| {
                message.app_id == self.config.app_id
                    && message.kind == PrivateMessageKind::PrivatePaymentList.as_str()
            })
            .map(|message| message.outbound_message_id)
            .max();
        let statuses = messages
            .into_iter()
            .map(|message| (message.outbound_message_id, message.status))
            .collect::<HashMap<_, _>>();
        // A Sent row alone can come from restored/shared state. Require
        // this runtime's successful publication on the current link,
        // and refuse a witness superseded by a newer local publication.
        let acknowledged = matches!(readiness, Ok(PrivateQueueReadiness::Ready))
            .then(|| self.published_private_payment_list_id(tx, counterparty))
            .flatten()
            .filter(|id| tracked.contains(id))
            // Another commit may complete after Sent released its lease
            // but before this runtime updates its publication witness.
            // A newer list also makes an older clear unsafe to retain.
            .filter(|id| latest_list_id == Some(*id))
            .filter(|id| {
                matches!(statuses.get(id), Some(OutboundPrivateMessageStatus::Sent))
            });
        Ok((handshake_pending, statuses, acknowledged))
    })
    .await?;
// Acknowledgements never suppress queue, reservation, or delivery errors.
if let Some(outbound_message_id) = acknowledged {
    let entry = PrivatePaymentListAcknowledgement {
        counterparty: counterparty.clone(),
        outbound_message_id,
    };
    if !report.acknowledged.contains(&entry) {
        report.acknowledged.push(entry);
    }

